def calculate_factorial(n: int) -> int:
    """
    Computes the factorial of a non-negative integer n.

    The factorial of 0 is 1.
    For example, calculate_factorial(5) should return 120.
    """
    if n < 0:
        raise ValueError("Factorial is not defined for negative numbers.")
    elif n == 0:
        return 1
    else:
        result: int = 1
        for i in range(1, n + 1):
            result *= i
        return result

def main() -> None:
    test_cases: list[tuple[int, int]] = [(0, 1), (1, 1), (5, 120), (7, 5040)]
    for num, expected in test_cases:
        actual_result: int = calculate_factorial(num)
        print(f"Factorial of {num} is {actual_result}. Expected: {expected}.")
        assert actual_result == expected, f"Test failed for {num}. Expected {expected}, got {actual_result}"

if __name__ == "__main__":
    main()

