def fibonacci_sequence(n: int) -> list[int]:
    """
    Generates the first n numbers of the Fibonacci sequence.

    The sequence starts with 0 and 1.
    """
    if n <= 0:
        return []
    elif n == 1:
        return [0]
    else:
        sequence: list[int] = [0, 1]
        for _ in range(2, n):
            next_fib: int = sequence[-1] + sequence[-2]
            sequence.append(next_fib)
        return sequence

def main() -> None:
    """
    Main function to demonstrate fibonacci_sequence.
    """
    test_cases: list[int] = [0, 1, 2, 5, 10]
    for n_val in test_cases:
        result: list[int] = fibonacci_sequence(n_val)
        print(f"fibonacci_sequence({n_val}) = {result}")

