def merge_dictionaries(dict1: dict, dict2: dict) -> dict:
    """
    Merges two dictionaries, with values from dict2 overriding dict1 on key overlap.

    Args:
        dict1: The first dictionary.
        dict2: The second dictionary.

    Returns:
        A new dictionary containing the merged key-value pairs.
    """
    merged_dict: dict = dict1.copy()
    for key, value in dict2.items():
        merged_dict[key] = value
    return merged_dict

def example_usage() -> None:
    d1: dict[str, int] = {'a': 1, 'b': 2}
    d2: dict[str, int] = {'b': 3, 'c': 4}
    result: dict[str, int] = merge_dictionaries(d1, d2)
    print(f"Merged dictionary: {result}")

