def caesar_cipher_encrypt(text: str, shift: int) -> str:
    """Encrypts a string using a Caesar cipher."""
    result: list[str] = []
    for char in text:
        if 'a' <= char <= 'z':
            shifted_char: str = chr(((ord(char) - ord('a') + shift) % 26) + ord('a'))
            result.append(shifted_char)
        elif 'A' <= char <= 'Z':
            shifted_char: str = chr(((ord(char) - ord('A') + shift) % 26) + ord('A'))
            result.append(shifted_char)
        else:
            result.append(char)
    return "".join(result)

def main() -> None:
    test_cases: dict[tuple[str, int], str] = {
        ('abc', 1): 'bcd',
        ('xyz', 3): 'abc',
        ('Hello, World!', 3): 'Khoor, Zruog!',
        ('123', 5): '123'
    }
    for (text, shift), expected in test_cases.items():
        encrypted_text: str = caesar_cipher_encrypt(text, shift)
        print(f"Encrypting '{text}' with shift {shift}: '{encrypted_text}' (Expected: '{expected}')")
        assert encrypted_text == expected, f"Test failed for '{text}', shift {shift}. Expected: '{expected}', Got: '{encrypted_text}'"

