from collections import Counter

def most_frequent_char(text: str) -> str:
    """
    Returns the character that appears most frequently in a string.
    Ignores spaces and case. If ties, returns the one that appears first.
    """
    cleaned_text: str = "".join(char.lower() for char in text if char.isalpha())
    if not cleaned_text:
        return ''

    char_counts: Counter[str] = Counter()
    for char in cleaned_text:
        char_counts[char] += 1

    max_count: int = -1
    most_frequent: str = ''
    first_occurrence_index: dict[str, int] = {}

    for i, char in enumerate(cleaned_text):
        if char not in first_occurrence_index:
            first_occurrence_index[char] = i

    for char, count in char_counts.items():
        if count > max_count:
            max_count = count
            most_frequent = char
        elif count == max_count:
            if first_occurrence_index[char] < first_occurrence_index[most_frequent]:
                most_frequent = char

    return most_frequent

