def portfolio_value(stocks: dict[str, int], prices: dict[str, float]) -> float:
    """
    Calculates the total value of a stock portfolio.

    Args:
        stocks: A dictionary where keys are stock tickers (str) and values are quantities (int).
        prices: A dictionary where keys are stock tickers (str) and values are prices per share (float).

    Returns:
        The total value of the portfolio (float).
    """
    total_value: float = 0.0
    for ticker, quantity in stocks.items():
        if ticker in prices:
            price_per_share: float = prices[ticker]
            total_value += quantity * price_per_share
    return total_value

def main() -> None:
    example_stocks: dict[str, int] = {'AAPL': 10, 'GOOG': 5}
    example_prices: dict[str, float] = {'AAPL': 150.5, 'GOOG': 1000.25, 'MSFT': 300.0}

